stepxmp.pre:
table   { display: table; }
caption { display: table-caption; }
header  { display: table-header-group; }
body    { display: table-row-group; }
row     { display: table-row; }
cell    { display: table-cell; padding: 2pt 6pt; }

caption {
    display: table-caption;
    caption-side: bottom;
    text-align: center;
    font-style: italic;
}

col { display: table-column; }
col[name="item"]  { width: 120pt; }
col[name="price"] { background-color: #f5f5f5; }

cell[span] {
    border-right-style: hidden;
}

cell[span] + cell {
    display: contents;
    content: "";
}

cell[span] + cell::before,
cell[span] + cell::after {
    display: table-cell;
    border: 1pt solid;
    padding: 2pt 6pt;
}

cell[span] + cell::before {
    content: "";
}

cell[span] + cell::after {
    content: contents;
}
